public class Main {
    public static void main(String[] args) throws Exception {
        final ConcurrentStack<Integer> stack = new ConcurrentStack<Integer>();
        ExecutorService es = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 2; i++) {
            final int base = i * 10;
            es.execute(() -> {
                for (int j = 0; j < 5; j++) {
                    stack.push(base + j);
                    System.out.println("Pushed " + (base + j));
                }
                for (int j = 0; j < 5; j++) {
                    Integer v = stack.pop();
                    System.out.println("Popped " + v);
                }
            });
        }
